// Geocode uniquement les clients nouveaux ou dont l'adresse a change (Geoplateforme IGN, gratuit)
const cache = {};
for (const r of $input.all()) { if (r.json && r.json.client_id) cache[r.json.client_id] = r.json; }
const clients = $('Normaliser').all().map(i => i.json);
const todo = clients.filter(c => { const k = cache[c.client_id]; return !k || k.adresse !== c.adresse || k.nom !== c.nom || k.lat === null || k.lat === undefined; }).slice(0, 1500);
const geo = async (c) => {
  const k = cache[c.client_id];
  if (k && k.adresse === c.adresse && k.lat !== null && k.lat !== undefined) return Object.assign({}, c, { lat: k.lat, lon: k.lon, score: k.score });
  for (let essai = 0; essai < 2; essai++) {
    try {
      const r = await this.helpers.httpRequest({ method: 'GET', url: 'https://data.geopf.fr/geocodage/search', qs: { q: c.adresse, limit: 1, index: 'address' }, json: true });
      const f = (r.features || [])[0];
      if (!f) return Object.assign({}, c, { lat: null, lon: null, score: 0 });
      return Object.assign({}, c, { lat: f.geometry.coordinates[1], lon: f.geometry.coordinates[0], score: Math.round((f.properties.score || 0) * 100) / 100 });
    } catch (e) { /* 429 ou reseau : on retente une fois */ }
  }
  return null;
};
const out = [];
for (let i = 0; i < todo.length; i += 4) {
  const lot = await Promise.all(todo.slice(i, i + 4).map(geo));
  for (const x of lot) if (x) out.push({ json: x });
}
return out;

const out = [];
const vus = new Set();
for (const it of $input.all()) {
  for (const c of (it.json.items || [])) {
    if (vus.has(c.id)) continue;
    vus.add(c.id);
    if (String(c.category || '') === 'supplier') continue;
    const a = c.address || {};
    if (!a.address || !a.city) continue;
    const adresse = [a.address, a.zipCode, a.city].map(s => String(s || '').trim()).filter(Boolean).join(' ');
    out.push({ json: { client_id: String(c.id), ref: String(c.reference || ''), nom: String(c.name || '').trim(), adresse } });
  }
}
return out;
